cypress_script:
describe('Student Registration Practice Form', () => {
  it('should submit the form with valid data', () => {
    cy.visit('https://demoqa.com/automation-practice-form');
    cy.get('#firstName').type('John');
    cy.get('#lastName').type('Doe');
    cy.get('#userEmail').type('john.doe@example.com');
    cy.get('#gender-radio-1').check();
    cy.get('#userNumber').type('1234567890');
    cy.get('#dateOfBirthInput').type('20 Jul 2026');
    cy.get('#subjectsInput').type('Mathematics');
    cy.get('#hobbies-checkbox-1').check();
    cy.get('#currentAddress').type('123 Main St');
    cy.get('#submit').click();
    cy.url().should('include', '/automation-practice-form');
  });

  it('should not submit the form when required fields are empty', () => {
    cy.visit('https://demoqa.com/automation-practice-form');
    cy.get('#submit').click();
    cy.url().should('include', '/automation-practice-form');
    cy.get('#firstName').should('be.visible');
    cy.get('#lastName').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Student Registration Practice Form', () => {
  test('should submit the form with valid data', async ({ page }) => {
    await page.goto('https://demoqa.com/automation-practice-form');
    await page.fill('#firstName', 'John');
    await page.fill('#lastName', 'Doe');
    await page.fill('#userEmail', 'john.doe@example.com');
    await page.check('#gender-radio-1');
    await page.fill('#userNumber', '1234567890');
    await page.fill('#dateOfBirthInput', '20 Jul 2026');
    await page.fill('#subjectsInput', 'Mathematics');
    await page.check('#hobbies-checkbox-1');
    await page.fill('#currentAddress', '123 Main St');
    await page.click('#submit');
    await expect(page).toHaveURL(/.*automation-practice-form/);
  });

  test('should not submit the form when required fields are empty', async ({ page }) => {
    await page.goto('https://demoqa.com/automation-practice-form');
    await page.click('#submit');
    await expect(page).toHaveURL(/.*automation-practice-form/);
    await expect(page.locator('#firstName')).toBeVisible();
    await expect(page.locator('#lastName')).toBeVisible();
  });
});
